type PrinterActorSnapshot={stableId:string;printerId:string;modelId?:string;host:string;activePort:number;activeProtocol:string;sessionEpoch:number;phase:PrinterActorPhase;connected:boolean;lastSeenAt?:number;telemetryUpdatedAt?:number;jobUpdatedAt?:number;cachedStatus?:Record<string,any>;capabilities:PrinterActorCapabilities;lastError?:string;presentation?:PrinterActorPresentation};
type PrinterActorEvent={eventId:number;stableId:string;printerId:string;sessionEpoch:number;kind:string;phase:PrinterActorPhase;eventtime?:number;status?:Record<string,any>;operationId?:string;payload?:unknown};
