import { useEffect, useId, useState } from 'react';
import { Lightbulb, LoaderCircle, RefreshCw } from 'lucide-react';
import type { PrinterLightState } from '../lib/printerLight';
import styles from './PrinterLightControl.module.css';

export function PrinterLightControl({light,online,busy,onToggle,onRetry}:{light?:PrinterLightState;online:boolean;busy:boolean;onToggle:(on:boolean)=>void;onRetry:()=>void}){
 const statusId=useId();
 const [requested,setRequested]=useState<boolean>();
 const [draft,setDraft]=useState<number>();
 const confirmed=light?.supported===true?light.on:undefined;
 const enabled=online&&light?.supported===true&&!busy;
 useEffect(()=>{
  if(!busy&&(confirmed!==undefined||!light)){setRequested(undefined);setDraft(undefined)}
 },[busy,confirmed,light]);
 const value=draft??(requested===undefined?(confirmed===undefined?1:confirmed?2:0):requested?2:0);
 const status=!online?'Нет связи':busy?'Переключение…':!light?'Проверяем…':!light.supported?'Недоступна':confirmed!==undefined?confirmed?'Включена':'Выключена':requested!==undefined?'Не подтверждено':'Не определено';
 const description=!online?'Нет связи с принтером':busy?'Ожидаем подтверждение от принтера':confirmed!==undefined?`Подсветка ${confirmed?'включена':'выключена'}`:requested!==undefined?`${requested?'Включение':'Выключение'} подсветки не подтверждено принтером. ${light?.detail??''}`:light?.detail??'Потяните влево, чтобы выключить, или вправо, чтобы включить';
 const change=(position:number)=>{
  setDraft(position);
  // The middle position is an unknown state, never an implicit ON command.
  if(position===1)return;
  const on=position===2;
  setDraft(undefined);
  if(confirmed===on){setRequested(undefined);return}
  setRequested(on);onToggle(on);
 };
 return <section className={styles.control} aria-label="Подсветка принтера" title={description}>
  <div className={styles.heading}><span><Lightbulb/><b>Подсветка</b></span><span id={statusId} className={styles.status} aria-live="polite">{busy&&<LoaderCircle className="spin"/>}{status}</span>{online&&!busy&&confirmed===undefined&&<button type="button" className={styles.retry} aria-label="Проверить подсветку снова" title="Проверить подсветку снова" onClick={onRetry}><RefreshCw/></button>}</div>
  <input className={styles.slider} type="range" min="0" max="2" step="1" value={value} aria-label="Подсветка" aria-describedby={statusId} aria-valuetext={description} data-confirmed={confirmed===undefined?'unknown':confirmed?'on':'off'} disabled={!enabled} onChange={event=>change(Number(event.target.value))}/>
  <div className={styles.endpoints} aria-hidden="true"><span>Выкл.</span><span>Вкл.</span></div>
 </section>
}

