import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import http from 'node:http';
import {build} from 'vite';
import ts from '../scripts/typescript-runtime.mjs';
const root=path.resolve(import.meta.dirname,'..'),out=fs.mkdtempSync(path.join(os.tmpdir(),'kf-r100-'));
const {chromium}=await import(process.env.PLAYWRIGHT_MODULE_PATH??'playwright');
const js=ts.transpileModule(fs.readFileSync(path.join(root,'src/lib/printerLight.ts'),'utf8'),{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ES2022}}).outputText;
const light=await import(`data:text/javascript;base64,${Buffer.from(js).toString('base64')}`);
assert.equal(light.discoverPrinterLight(['output_pin fan0','output_pin power','heater_bed']),undefined);
assert.equal(light.printerLightCommand(light.discoverPrinterLight(['output_pin Led_Pin']),false),'SET_PIN PIN=Led_Pin VALUE=0');
await build({root,logLevel:'warn',build:{outDir:out,emptyOutDir:true,rollupOptions:{input:[path.join(root,'ui-tests/design-layout.html'),path.join(root,'ui-tests/notifications-r100.html')]}}});
const server=http.createServer((req,res)=>{const file=path.resolve(out,new URL(req.url,'http://localhost').pathname.slice(1));if(!file.startsWith(out+path.sep)||!fs.existsSync(file)){res.writeHead(404);res.end();return}res.setHeader('Content-Type',({'.js':'text/javascript','.css':'text/css','.html':'text/html'})[path.extname(file)]??'application/octet-stream');res.end(fs.readFileSync(file))});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE,args:['--no-sandbox','--disable-dev-shm-usage']});
const base=`http://127.0.0.1:${server.address().port}/ui-tests/`,screenshots=process.env.KF_UI_SCREENSHOTS;
if(screenshots)fs.mkdirSync(screenshots,{recursive:true});
try{
 for(const mode of ['normal','config','catalog-error','numeric-string','raw','error','ignored','absent','k1-unknown','get-only']){
  const page=await browser.newPage({viewport:{width:1366,height:900}}),errors=[];page.on('pageerror',e=>errors.push(e.message));
  console.log('Light case:',mode);
  await page.goto(base+`design-layout.html?view=printer&light=${mode}`);
  const slider=page.getByRole('slider',{name:'Подсветка',exact:true});await slider.waitFor();
  if(mode==='absent'){
   assert.equal(await slider.isDisabled(),true);
   assert.ok(await page.getByRole('button',{name:'Проверить подсветку снова',exact:true}).isEnabled());
   assert.deepEqual(await page.evaluate(()=>window.__lightCalls),[]);
  }else if(mode==='k1-unknown'){
   await page.waitForFunction(()=>document.querySelector('input[aria-label="Подсветка"]')?.disabled===false);
   assert.equal(await slider.inputValue(),'1','unknown starts neutral and can explicitly switch OFF');
   await slider.press('Home');assert.ok(await slider.isDisabled());
   await page.locator('.appToast.danger').waitFor();
   await page.waitForFunction(()=>document.querySelector('input[aria-label="Подсветка"]')?.disabled===false);
   assert.equal(await slider.getAttribute('data-confirmed'),'unknown','unknown readback is never confirmed');
   assert.deepEqual(await page.evaluate(()=>window.__lightCalls),['SET_PIN PIN=LED VALUE=0']);
   assert.ok((await page.evaluate(()=>window.__lightHttpCalls)).length>=1,'unknown RPC uses read-only GET');
   if(screenshots)await page.screenshot({path:path.join(screenshots,'r100-k1-unknown.png'),fullPage:true});
  }else{
   await page.waitForFunction(()=>document.querySelector('input[aria-label="Подсветка"]')?.getAttribute('data-confirmed')==='on');
   assert.equal(await slider.inputValue(),'2');
   await slider.press('Home');assert.ok(await slider.isDisabled());
   await page.waitForFunction(()=>document.querySelector('input[aria-label="Подсветка"]')?.disabled===false);
   assert.equal(await slider.getAttribute('data-confirmed'),['error','ignored'].includes(mode)?'on':'off');
   assert.equal(await slider.inputValue(),['error','ignored'].includes(mode)?'2':'0');
   if(['error','ignored'].includes(mode))await page.locator('.appToast.danger').waitFor();
   else {await slider.press('End');await page.waitForFunction(()=>document.querySelector('input[aria-label="Подсветка"]')?.disabled===false);assert.equal(await slider.getAttribute('data-confirmed'),'on');assert.deepEqual(await page.evaluate(()=>window.__lightCalls),['SET_PIN PIN=LED VALUE=0','SET_PIN PIN=LED VALUE=1'])}
   if(mode==='get-only')assert.ok((await page.evaluate(()=>window.__lightHttpCalls)).length>=3,'GET-only firmware confirms initial/OFF/ON states');
   if(screenshots&&mode==='config')await page.screenshot({path:path.join(screenshots,'r100-light.png'),fullPage:true});
  }
  assert.deepEqual(errors,[]);await page.close();
 }
 for(const theme of ['dark','light'])for(const width of [1366,390])for(const mode of ['ok','fail']){
  const page=await browser.newPage({viewport:{width,height:900}}),errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.goto(base+`notifications-r100.html?native=${mode}`);await page.evaluate(theme=>document.documentElement.dataset.theme=theme,theme);
  const test=page.getByRole('button',{name:'Проверить уведомления',exact:true});await test.click();
  await page.getByText('Проверка уведомлений',{exact:true}).waitFor();
  assert.ok(await page.getByRole('button',{name:'Проверяем…'}).isDisabled());
  await test.waitFor();
  await page.getByText(mode==='ok'?/Запрос Windows отправлен/:/Windows: Windows notifications disabled/).first().waitFor();
  assert.equal((await page.evaluate(()=>window.__calls.filter(x=>x.command==='native_notify'))).length,1);
  await page.getByRole('button',{name:/^Уведомления/}).click();
  await page.locator('.notificationList article').filter({hasText:'Проверка уведомлений'}).waitFor();
  assert.equal(await page.locator('.notificationList article').count(),1);
  await page.evaluate(()=>window.__failList=true);await page.getByRole('button',{name:'Обновить уведомления',exact:true}).click();await page.getByText(/Не удалось загрузить уведомления/).waitFor();
  assert.equal(await page.getByText('Всё спокойно',{exact:true}).count(),0);
  await page.evaluate(()=>window.__failList=false);await page.getByRole('button',{name:'Обновить уведомления',exact:true}).click();await page.locator('.notificationLoadError').waitFor({state:'detached'});
  if(screenshots&&width===1366&&mode==='ok')await page.screenshot({path:path.join(screenshots,`r100-notifications-${theme}.png`),fullPage:true});
  assert.ok(await page.locator('.notificationDrawer').evaluate(el=>el.getBoundingClientRect().right<=innerWidth+1));
  assert.deepEqual(errors,[]);await page.close();
 }
 for(const mode of ['current','available','fail']){
  const page=await browser.newPage();await page.goto(base+`notifications-r100.html?update=${mode}`);
  const check=page.getByRole('button',{name:'Проверить обновления',exact:true});await check.click();await page.getByRole('button',{name:'Проверяем…'}).waitFor();await check.waitFor();
  await page.locator(mode==='fail'?'.appToast.danger':'.appToast.success').waitFor();
  await page.getByRole('button',{name:/^Уведомления/}).click();await page.locator('.notificationList article').waitFor();
  const calls=await page.evaluate(()=>window.__calls);assert.equal(calls.filter(x=>x.command==='update_check').length,1);assert.equal(calls.filter(x=>x.command==='audit_add').length,1);
  await page.close();
 }
 console.log('R100 passed: ten light discovery/readback cases including GET-only firmware; eight notification layouts with native success/failure, visible test, saved history, database failure/recovery; three update outcomes.');
}finally{await browser.close();await new Promise(resolve=>server.close(resolve));fs.rmSync(out,{recursive:true,force:true})}

