import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import http from 'node:http';
import {build} from 'vite';
const root=path.resolve(import.meta.dirname,'..'),out=fs.mkdtempSync(path.join(os.tmpdir(),'kf-light-compact-'));
const {chromium}=await import(process.env.PLAYWRIGHT_MODULE_PATH??'playwright');
const shots=process.env.KF_UI_SCREENSHOTS,report=[];
let server,browser;
try{
 await build({root,logLevel:'warn',build:{outDir:out,emptyOutDir:true,rollupOptions:{input:path.join(root,'ui-tests/design-layout.html')}}});
 server=http.createServer((req,res)=>{const file=path.resolve(out,new URL(req.url,'http://localhost').pathname.slice(1));if(!file.startsWith(out+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile()){res.writeHead(404).end();return}res.setHeader('Content-Type',({'.js':'text/javascript','.css':'text/css','.html':'text/html','.png':'image/png','.svg':'image/svg+xml','.webp':'image/webp'})[path.extname(file)]??'application/octet-stream');res.end(fs.readFileSync(file))});
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
 const origin=`http://127.0.0.1:${server.address().port}`;
 browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE,args:['--no-sandbox','--disable-dev-shm-usage']});
 if(shots)fs.mkdirSync(shots,{recursive:true});
 for(const theme of ['dark','light'])for(const [width,height] of [[1920,1200],[1366,768],[390,844]]){
  const page=await browser.newPage({viewport:{width,height},locale:'ru-RU'}),errors=[];
  page.on('pageerror',error=>errors.push(error.message));
  await page.route('**/*',route=>route.request().url().startsWith(origin+'/')?route.continue():route.abort());
  await page.goto(origin+'/ui-tests/design-layout.html?view=printer&light=get-only');
  await page.evaluate(theme=>document.documentElement.dataset.theme=theme,theme);
  const light=page.getByRole('slider',{name:'Подсветка',exact:true});
  await page.waitForFunction(()=>document.querySelector('input[aria-label="Подсветка"]')?.getAttribute('data-confirmed')==='on');
  const utilities=page.locator('.kfDetailUtilities');await utilities.scrollIntoViewIfNeeded();
  const geometry=await utilities.evaluate(el=>{const r=el.getBoundingClientRect();return{width:r.width,height:r.height,right:r.right,x:r.x,overflow:el.scrollWidth>el.clientWidth+1,sliders:Array.from(el.querySelectorAll('input[type=range]')).map(input=>{const b=input.getBoundingClientRect();return{width:b.width,height:b.height,x:b.x,y:b.y,right:b.right}})}});
  assert.equal(geometry.overflow,false);assert.ok(geometry.width<=1041);assert.ok(geometry.x>=0&&geometry.right<=width+1);assert.equal(geometry.sliders.length,3);
  assert.ok(geometry.sliders.every(slider=>slider.width<=360&&slider.height<=26),JSON.stringify(geometry));
  if(width>=1201){assert.ok(geometry.height<=105,JSON.stringify(geometry));assert.ok(Math.max(...geometry.sliders.map(s=>s.y))-Math.min(...geometry.sliders.map(s=>s.y))<=1,'all three sliders share one row')}
  else {assert.ok(geometry.height<=230,JSON.stringify(geometry));assert.ok(geometry.sliders[2].y>geometry.sliders[1].y&&geometry.sliders[1].y>geometry.sliders[0].y,'mobile controls stack')}
  assert.equal(await utilities.getByRole('button',{name:/^(Включить|Выключить)$/}).count(),0);
  if(width===1920){
   const box=await light.boundingBox();
   await page.mouse.move(box.x+box.width-8,box.y+box.height/2);await page.mouse.down();await page.mouse.move(box.x+8,box.y+box.height/2,{steps:12});await page.mouse.up();
   await page.waitForFunction(()=>document.querySelector('input[aria-label="Подсветка"]')?.getAttribute('data-confirmed')==='off');assert.equal(await light.inputValue(),'0');
   await page.mouse.move(box.x+8,box.y+box.height/2);await page.mouse.down();await page.mouse.move(box.x+box.width-8,box.y+box.height/2,{steps:12});await page.mouse.up();
   await page.waitForFunction(()=>document.querySelector('input[aria-label="Подсветка"]')?.getAttribute('data-confirmed')==='on');assert.equal(await light.inputValue(),'2');
   assert.deepEqual(await page.evaluate(()=>window.__lightCalls),['SET_PIN PIN=LED VALUE=0','SET_PIN PIN=LED VALUE=1'],'one command for each physical drag');
  }
  assert.deepEqual(errors,[]);
  if(shots){await page.screenshot({path:path.join(shots,`compact-panel-${theme}-${width}.png`)});await utilities.screenshot({path:path.join(shots,`compact-controls-${theme}-${width}.png`)})}
  report.push({theme,width,height,geometry,passed:true});await page.close();
 }
 const result={passed:report.length,report,notes:'Actual ControlPanel and production CSS. Exact read-only HTTP fallback emulated; no physical printer access.'};
 if(shots)fs.writeFileSync(path.join(shots,'light-compact-r116-report.json'),JSON.stringify(result,null,2));
 console.log('R116 compact light acceptance passed: '+report.length+' real panel layouts; physical pointer OFF/ON each sends exactly one command; GET fallback readback confirmed.');
}finally{await browser?.close();if(server)await new Promise(resolve=>server.close(resolve));fs.rmSync(out,{recursive:true,force:true})}
